<?php
namespace App\Filament\Admin\Resources\Proposals\Pages;use App\Domain\Tenancy\TenantContext;use App\Filament\Admin\Concerns\ServiceValidation;use App\Filament\Admin\Resources\Proposals\ProposalResource;use App\Models\{PaymentIntentRecord,Tenant};use Filament\Actions\Action;use Filament\Forms\Components\{DateTimePicker,Select,TextInput};use Filament\Resources\Pages\ViewRecord;final class ViewProposal extends ViewRecord{protected static string $resource=ProposalResource::class;protected function getHeaderActions():array{return[Action::make('requestIssuance')->label('Request issuance')->icon('heroicon-o-shield-check')->visible(fn()=>$this->record->status==='PAYMENT_PENDING')->schema([Select::make('payment_intent_id')->options(fn()=>PaymentIntentRecord::where(['tenant_id'=>$this->record->tenant_id,'proposal_id'=>$this->record->id,'status'=>'SUCCEEDED'])->whereNotNull('reconciled_at')->pluck('provider_reference','id'))->required()->searchable(),Select::make('delegated_authority_agreement_id')->options(fn()=>\Illuminate\Support\Facades\DB::table('delegated_authority_agreements as authority')->join('partners','partners.id','=','authority.partner_id')->where('authority.carrier_id',$this->record->offer->carrier_id)->where('partners.tenant_id',$this->record->tenant_id)->where('authority.status','ACTIVE')->pluck('authority.agreement_number','authority.id'))->searchable(),TextInput::make('territory')->required()->maxLength(80),DateTimePicker::make('coverage_starts_at')->required(),DateTimePicker::make('coverage_ends_at')->required()->after('coverage_starts_at')])->action(function(array$d){$payment=PaymentIntentRecord::findOrFail($d['payment_intent_id']);if(ServiceValidation::run(fn()=>app(\App\Application\Policies\PolicyIssuanceService::class)->request(Tenant::findOrFail(app(TenantContext::class)->id()),$this->record,$payment,$d,auth()->user()))===null)return;})];}}
